// Author: MiYu. Cross-API shop, queue and food consumers on copied original geometry; run with the stage batch.
#include "session.h"
#include "setup.h"
#include <bit>
#include <iostream>
#include <algorithm>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_commerce_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();
        auto& vm=session.runtime();auto id=vm.global("probe_barracks").bits,buyer=vm.global("probe_buyer").bits,shop=vm.global("probe_shop").bits;auto& states=session.config().players[0].states;auto check=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};check(vm.global("probe_sold").bits==1 && vm.global("probe_items").bits==1,"Sale event context did not reach actual script consumer");check(states.at(1)==8930 && session.units().at(id)->production.size()==1,"Paid queue cancellation/refund differs");check(session.units().at(buyer)->inventory[0]!=0,"Purchased item not carried");check(states.at(5)==7,"Food reservation was not released by cancellation");auto commands=session.commands(shop,0);check(std::any_of(commands.begin(),commands.end(),[](auto& b){return b.type==ObjectData::code("hfoo") && b.stock==0 && !b.enabled;}),"Empty stock was not consumed by command model");
        for(auto name:{"GetHeroXP","GetHeroLevel","GetHeroSkillPoints"}){check(vm.invoke(name,std::array{vm.handle("unit",0)}).bits==0,"Null hero query did not return zero");check(vm.invoke(name,std::array{vm.handle("unit",id)}).bits==0,"Nonhero query did not return zero");}check(vm.invoke("GetHeroLevel",std::array{vm.handle("unit",buyer)}).bits==1,"Live hero level query differs");check(!vm.invoke("UnitItemInSlot",std::array{vm.handle("unit",0),vm.integer(0)}).bits && !vm.invoke("UnitInventorySize",std::array{vm.handle("unit",0)}).bits,"Null inventory query was not empty");check(vm.invoke("UnitItemInSlot",std::array{vm.handle("unit",buyer),vm.integer(0)}).bits==session.units().at(buyer)->inventory[0],"Live inventory query differs");
        session.advance(21);check(vm.global("probe_finished").bits==1 && vm.global("probe_started").bits==2 && vm.global("probe_cancelled").bits==1,"Training lifecycle event consumer differs");auto trained=vm.global("probe_trained").bits;check(session.units().contains(trained) && session.units().at(id)->production.empty(),"Training completion did not create unit");auto score=[&](unsigned owner,unsigned category){return std::bit_cast<std::int32_t>(vm.invoke("GetPlayerScore",std::array{vm.handle("player",0x100000+owner),vm.handle("playerscore",category)}).bits);};auto footman=session.product(ObjectData::code("hfoo"));check(score(0,21)==footman.gold+footman.lumber && score(0,24)==score(0,21)+score(0,22)+score(0,23),"Trained unit value was not included in player scores");check(states.at(5)==9,"Completed unit double-counted reserved food");check(!session.units().at(trained)->route.empty(),"Rally command was not consumed");session.advance(10);commands=session.commands(shop,0);check(std::any_of(commands.begin(),commands.end(),[](auto& b){return b.type==ObjectData::code("hfoo") && b.stock==1 && b.enabled;}),"Shop stock did not replenish");
        auto handle=vm.handle("unit",trained);vm.invoke("KillUnit",std::array{handle});check(states.at(5)==7,"Death did not release food");vm.invoke("RemoveUnit",std::array{handle});check(states.at(5)==7,"Removal released dead unit food twice");auto hero=vm.handle("unit",buyer);vm.invoke("SetUnitOwner",std::array{hero,vm.handle("player",0x100001),vm.boolean(true)});check(states.at(5)==2 && session.config().players[1].states.at(5)==5,"Ownership did not transfer food");vm.invoke("ProbeHero");check(vm.global("probe_levelled").bits==2 && vm.global("probe_learned").bits==1 && std::bit_cast<float>(session.units().at(buyer)->maxLife.bits())==850,"Hero experience/attributes/skill consumers differ");check(score(0,22)==0 && score(1,22)==500 && score(1,24)==score(1,21)+score(1,22)+score(1,23),"Hero score did not follow owner and current experience");vm.invoke("ProbeIllusion");auto clone=vm.global("probe_illusion").bits;check(vm.global("probe_summons").bits==1 && vm.global("probe_damage").bits==1 && session.units().at(clone)->illusion && session.config().players[1].states.at(5)==5,"Illusion producer/damage or no-food consumer differs");session.advance(2.125);check(session.units().contains(clone),"Paused timed life expired");vm.invoke("ProbeResumeIllusion");session.advance(2.125);check(!session.units().contains(clone) && session.config().players[1].states.at(5)==5,"Illusion expiry/removal altered real unit population");vm.invoke("ProbeQuest");check(session.quests().size()==1 && session.quests().begin()->second->items.front().second->completed && session.questFlash(),"Quest handle/objective/notification consumer differs");vm.invoke("ProbeBlight");auto acolyte=vm.global("probe_acolyte").bits;auto revision=session.world()->blightRevision();vm.invoke("ProbeRepeatBlight");check(session.world()->blightRevision()==revision,"Unchanged blight dirtied terrain again");session.advance(1);check(std::bit_cast<float>(session.units().at(acolyte)->life.bits())==102,"Blight regeneration not consumed");vm.invoke("ProbeClearBlight");session.advance(1);check(std::bit_cast<float>(session.units().at(acolyte)->life.bits())==102,"Regeneration continued off blight");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS commerce consumers: stock/sales/items, paid queue/refund, training events, food lifetime, rally, source heroes, custom abilities and item illusions\n";return 0;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
